import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring, Easing, Img } from "remotion";
import { COLORS, FONTS, STYLE } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const WHITE = "rgba(255,255,255,1)";
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const toItems = (v: unknown): string[] => {
  if (Array.isArray(v)) return v.map((x) => String(x ?? "").trim()).filter(Boolean);
  if (typeof v === "string") return v.split(/\n|\|/).map((x) => x.trim()).filter(Boolean);
  return [];
};

const ImagemListaPontos: React.FC<PrimitiveProps> = ({ anim, fps, format, frame }) => {
  const f = useCurrentFrame();
  const W = frame.width;
  const H = frame.height;
  const p = anim.params ?? {};
  const src = String(p.src ?? "");
  const title = String(p.title ?? anim.text ?? "").trim();
  const items = toItems(p.items ?? p.bullets);

  const landscape = format === "landscape";
  const half = format === "half";
  const u = landscape ? H / 1080 : W / 1080;
  const margin = 56 * u;
  const radius = STYLE.sharp ? 0 : 24 * u;

  // shrink type as the list gets longer — the panel grows, it never clips
  const chars = items.reduce((n, s) => n + s.length, 0);
  const fit = Math.max(0.6, Math.min(1, Math.sqrt((half ? 110 : landscape ? 160 : 200) / Math.max(1, chars))));
  const titleSize = (half ? 56 : landscape ? 64 : 76) * u * Math.max(0.65, Math.min(1, Math.sqrt(28 / Math.max(1, title.length))));
  const itemSize = (half ? 34 : landscape ? 36 : 44) * u * fit;

  const L = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const at = (q: number) => q * L;

  const imgIn = interpolate(f, [0, at(0.25)], [0, 1], { ...clamp, easing: Easing.out(Easing.cubic) });
  const panelIn = spring({ frame: f - at(0.06), fps, config: { damping: 18, stiffness: 120 }, durationInFrames: Math.max(8, Math.round(L * 0.18)) });
  const titleIn = interpolate(f, [at(0.14), at(0.26)], [0, 1], { ...clamp, easing: Easing.out(Easing.cubic) });
  const span = 0.45 / Math.max(1, items.length);
  const itemIn = (i: number) =>
    interpolate(f, [at(0.26 + i * span), at(0.26 + i * span + 0.1)], [0, 1], { ...clamp, easing: Easing.out(Easing.cubic) });

  const cols = landscape ? Math.min(3, Math.max(1, items.length)) : half && items.length > 3 ? 2 : 1;

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.body, overflow: "hidden" }}>
      {/* full-bleed image, no border */}
      {src ? (
        <Img
          src={src}
          style={{
            position: "absolute",
            inset: 0,
            width: "100%",
            height: "100%",
            objectFit: "cover",
            opacity: imgIn,
            transform: `scale(${1.08 - 0.08 * imgIn})`,
          }}
        />
      ) : (
        <div
          style={{
            position: "absolute",
            left: margin,
            right: margin,
            top: margin,
            height: H * (landscape ? 0.4 : half ? 0.35 : 0.42),
            borderRadius: radius,
            border: `${3 * u}px dashed rgba(255,255,255,.25)`,
            background: "rgba(255,255,255,.06)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontSize: 32 * u,
            color: COLORS.mutedOnLight,
            opacity: imgIn,
          }}
        >
          Imagem
        </div>
      )}

      {/* blue list panel on the bottom, grows upward with its content */}
      {title || items.length ? (
        <div
          style={{
            position: "absolute",
            left: margin,
            right: margin,
            bottom: margin,
            maxHeight: H - margin * 2,
            boxSizing: "border-box",
            padding: `${(half ? 32 : 44) * u}px ${(half ? 40 : 52) * u}px`,
            borderRadius: radius,
            background: COLORS.leather,
            opacity: Math.min(1, panelIn * 1.4),
            transform: `translateY(${(1 - panelIn) * 40}%)`,
          }}
        >
          {title ? (
            <div
              style={{
                fontFamily: FONTS.display,
                fontWeight: FONTS.displayWeight,
                fontSize: titleSize,
                lineHeight: 1.04,
                letterSpacing: "-0.01em",
                color: WHITE,
                overflowWrap: "break-word",
                marginBottom: items.length ? (half ? 20 : 28) * u : 0,
                opacity: titleIn,
                transform: `translateY(${(1 - titleIn) * 24 * u}px)`,
              }}
            >
              {title}
            </div>
          ) : null}
          <div
            style={{
              display: "grid",
              gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`,
              columnGap: 40 * u,
              rowGap: (half ? 14 : 22) * u,
            }}
          >
            {items.map((item, i) => {
              const t = itemIn(i);
              return (
                <div
                  key={i}
                  style={{
                    display: "flex",
                    alignItems: "flex-start",
                    gap: 20 * u,
                    opacity: t,
                    transform: `translateX(${(1 - t) * -40 * u}px)`,
                  }}
                >
                  <div
                    style={{
                      flexShrink: 0,
                      width: itemSize * 0.36,
                      height: itemSize * 0.36,
                      marginTop: itemSize * 0.42,
                      borderRadius: STYLE.sharp ? 0 : itemSize * 0.08,
                      background: COLORS.gold,
                      transform: `scale(${t})`,
                    }}
                  />
                  <div
                    style={{
                      fontWeight: Math.max(FONTS.bodyWeight, 500),
                      fontSize: itemSize,
                      lineHeight: 1.3,
                      color: WHITE,
                      overflowWrap: "break-word",
                      minWidth: 0,
                    }}
                  >
                    {item}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      ) : null}
    </AbsoluteFill>
  );
};

export default ImagemListaPontos;

