import React from 'react';
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring, Easing } from 'remotion';
import { COLORS, FONTS } from '../style-tokens';
import type { PrimitiveProps } from '../primitives';

const clamp = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;
const WHITE = 'rgba(255,255,255,1)';

const ImagemTopoListaAzul: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const frame = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const stacked = format === 'portrait';
  const T = Math.max(1, Math.round((anim.end - anim.start) * fps));

  const src = String(anim.params?.src ?? '');
  const title = typeof anim.params?.title === 'string' ? anim.params.title.trim() : '';
  const rawItems = anim.params?.items;
  const items = (
    Array.isArray(rawItems)
      ? rawItems.map((v) => String(v ?? ''))
      : String(typeof rawItems === 'string' && rawItems.trim() ? rawItems : anim.text ?? '').split(/\n|\|/)
  )
    .map((s) => s.trim())
    .filter(Boolean)
    .slice(0, 6);
  const n = items.length;

  const m = Math.min(W, H) * 0.067;

  // Portrait: image on top, blue panel below with the slash on its top edge.
  // Half/landscape: too short to stack, so image left, panel right with the slash on its left edge.
  const imgW = stacked ? W : W * 0.46;
  const imgH = stacked ? H * 0.46 : H;
  const slash = stacked ? W * 0.12 : H * 0.12;
  const panelL = stacked ? 0 : imgW - slash;
  const panelT = stacked ? imgH - slash : 0;
  const panelW = W - panelL;
  const panelH = H - panelT;
  const panelClip = stacked
    ? `polygon(0px ${slash}px, ${panelW}px 0px, ${panelW}px 100%, 0px 100%)`
    : `polygon(${slash}px 0px, ${panelW}px 0px, ${panelW}px 100%, 0px 100%)`;
  const padT = stacked ? slash + m * 0.6 : m;
  const padL = stacked ? m : slash + m * 0.6;
  const listW = panelW - padL - m;
  const listH = panelH - padT - m;

  // Fit type: shrink until the estimated block fits the panel (text wraps, never clips).
  let fs = stacked ? W * 0.048 : H * (format === 'half' ? 0.052 : 0.05);
  const estimate = (size: number) => {
    const cap = Math.max(4, (listW - size * 1.3) / (size * 0.56));
    const lines = items.reduce((acc, s) => acc + Math.ceil(s.length / cap), 0);
    const titleSize = size * 1.45;
    const titleCap = Math.max(4, listW / (titleSize * 0.55));
    const titleH = title ? Math.ceil(title.length / titleCap) * titleSize * 1.02 + size * 0.8 : 0;
    return titleH + lines * size * 1.3 + Math.max(0, n - 1) * size * 0.7;
  };
  while (estimate(fs) > listH * 0.92 && fs > 14) fs *= 0.93;
  const titleFs = fs * 1.45;

  const at = (p: number) => Math.round(p * T);
  const pop = (start: number, damping = 14) =>
    spring({ frame: frame - at(start), fps, durationInFrames: Math.max(2, Math.round(0.5 * fps)), config: { damping, mass: 0.7, stiffness: 140 } });

  const pImg = interpolate(frame, [0, at(0.2)], [0, 1], { ...clamp, easing: Easing.bezier(0.16, 1, 0.3, 1) });
  const pPanel = spring({ frame: frame - at(0.08), fps, durationInFrames: Math.max(2, Math.round(0.6 * fps)), config: { damping: 200 } });
  const pTitle = pop(0.18, 16);
  const itemStart = title ? 0.28 : 0.22;
  const step = n > 0 ? 0.55 / n : 0;

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.body, overflow: 'hidden' }}>
      {/* Image */}
      <div
        style={{
          position: 'absolute',
          left: 0,
          top: 0,
          width: imgW,
          height: imgH,
          overflow: 'hidden',
          opacity: interpolate(pImg, [0, 0.4], [0, 1], clamp),
        }}
      >
        {src ? (
          <Img
            src={src}
            style={{
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              scale: String(interpolate(frame, [0, T], [1.12, 1], clamp)),
            }}
          />
        ) : (
          <AbsoluteFill style={{ background: COLORS.vellum, justifyContent: 'center', alignItems: 'center' }}>
            <div style={{ width: Math.min(imgW, imgH) * 0.22, height: Math.min(imgW, imgH) * 0.15, background: 'rgba(255,255,255,0.08)' }} />
          </AbsoluteFill>
        )}
      </div>

      {/* Blue panel with the slash: title + bullets */}
      <div
        style={{
          position: 'absolute',
          left: panelL,
          top: panelT,
          width: panelW,
          minHeight: panelH,
          boxSizing: 'border-box',
          padding: `${padT}px ${m}px ${m}px ${padL}px`,
          background: COLORS.leather,
          clipPath: panelClip,
          translate: stacked ? `0px ${(1 - pPanel) * panelH}px` : `${(1 - pPanel) * panelW}px 0px`,
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
        }}
      >
        {title ? (
          <div
            style={{
              fontFamily: FONTS.display,
              fontWeight: FONTS.displayWeight,
              fontStyle: 'italic',
              textTransform: 'uppercase',
              fontSize: titleFs,
              lineHeight: 1.02,
              marginBottom: fs * 0.8,
              color: COLORS.gold,
              overflowWrap: 'break-word',
              opacity: interpolate(pTitle, [0, 0.4], [0, 1], clamp),
              translate: `0px ${(1 - pTitle) * fs}px`,
            }}
          >
            {title}
          </div>
        ) : null}
        {items.map((item, i) => {
          const p = pop(itemStart + i * step, 13);
          return (
            <div
              key={i}
              style={{
                display: 'flex',
                alignItems: 'flex-start',
                gap: fs * 0.55,
                marginTop: i === 0 ? 0 : fs * 0.7,
                opacity: interpolate(p, [0, 0.35], [0, 1], clamp),
                translate: `${(1 - p) * fs * 1.6}px 0px`,
              }}
            >
              <div
                style={{
                  flexShrink: 0,
                  width: fs * 0.5,
                  height: fs * 0.5,
                  marginTop: fs * 0.4,
                  background: COLORS.gold,
                  scale: String(interpolate(p, [0.2, 1], [0, 1], clamp)),
                }}
              />
              <div
                style={{
                  flex: 1,
                  minWidth: 0,
                  color: WHITE,
                  fontWeight: Math.max(500, FONTS.bodyWeight),
                  fontSize: fs,
                  lineHeight: 1.3,
                  overflowWrap: 'break-word',
                }}
              >
                {item}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

