  const items = toItems(p.items, String(anim.text ?? ""));
  const n = items.length;

  const land = format === "landscape";
  const half = format === "half";
  const u = land ? H / 1080 : W / 1080;
  const pad = (land ? 56 : half ? 48 : 72) * u;
  const slash = Math.min(W * 0.09, H * 0.08);

  // Shrink type for long lines and long lists so nothing is cut.
  const longest = Math.max(1, ...items.map((s) => s.length));
  const lenK = Math.max(0.6, Math.min(1, (land ? 28 : 36) / longest));
  const cap = land ? 4 : half ? 4 : 5;
  const countK = Math.max(0.6, Math.min(1, cap / Math.max(cap, n)));
