const toList = (v: unknown): string[] => {
  if (Array.isArray(v)) return v.map((x) => String(x ?? "").trim()).filter(Boolean);
  if (typeof v === "string") return v.split(/\n|\|/).map((s) => s.trim()).filter(Boolean);
  return [];
};

const ImagemListaTopicos: React.FC<PrimitiveProps> = ({ anim, fps, format, frame }) => {
  const f = useCurrentFrame();
  const len = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const p = anim.params ?? {};
  const src = String(p.src ?? "").trim();

  // Text: params.title/items win; otherwise anim.text lines (1st line = title when there are several).
  const lines = toList(anim.text ?? "");
  const hasParamTitle = typeof p.title === "string" && p.title.trim() !== "";
  const title = hasParamTitle ? String(p.title).trim() : lines.length > 1 ? lines[0] : "";
  let items = toList(p.items);
  if (!items.length) items = hasParamTitle ? lines : lines.length > 1 ? lines.slice(1) : lines;

  const W = frame.width;
  const H = frame.height;
  const landscape = format === "landscape";
  const half = format === "half";

