            background: "rgba(255,255,255,.06)",
            border: "2px dashed rgba(255,255,255,.25)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            opacity: imgIn,
          }}
        >
          <span style={{ color: COLORS.mutedOnLight, fontSize: base * 0.5, fontWeight: FONTS.bodyWeight }}>Imagem</span>
        </div>
      )}

      {showPanel && (
        <div
          style={{
            position: "absolute",
            bottom: margin,
            left: landscape ? "50%" : margin,
            width: landscape ? W * 0.66 : W - margin * 2,
            marginLeft: landscape ? -W * 0.33 : 0,
            boxSizing: "border-box",
            padding: `${base * 0.7}px ${base * 0.8}px`,
            borderRadius: radius,
            background: COLORS.leather,
            display: "flex",
            flexDirection: "column",
            gap: base * (half ? 0.3 : 0.38),
            opacity: panelIn,
            translate: `0px ${(1 - panelIn) * base * 1.2}px`,
          }}
        >
          {title !== "" && (
            <div
              style={{
                fontFamily: FONTS.display,
                fontWeight: FONTS.displayWeight,
                fontSize: titleSize,
                lineHeight: 1.04,
                letterSpacing: "-0.01em",
                color: COLORS.teal,
                textTransform: STYLE.uppercaseTitles ? "uppercase" : "none",
                overflowWrap: "break-word",
              }}
            >
              {title}
            </div>
          )}
          {items.map((item, i) => {
            const t = spring({
              frame: f - Math.round(firstAt + i * step),
              fps,
              config: { damping: 200 },
              durationInFrames: Math.round(0.5 * fps),
            });
            return (
              <div
                key={i}
                style={{
                  display: "flex",
                  alignItems: "flex-start",
                  gap: itemSize * 0.6,
                  opacity: t,
                  translate: `${(1 - t) * base * 0.6}px 0px`,
                }}
              >
                <div
                  style={{
                    flex: "0 0 auto",
                    width: itemSize * 0.42,
                    height: itemSize * 0.42,
                    marginTop: itemSize * 0.46,
                    borderRadius: STYLE.sharp ? 0 : itemSize * 0.1,
                    background: COLORS.gold,
                  }}
                />
                <div
                  style={{
                    fontSize: itemSize,
                    lineHeight: 1.35,
                    fontWeight: FONTS.bodyWeight,
                    color: "rgba(255,255,255,1)",
                    overflowWrap: "break-word",
                    minWidth: 0,
                  }}
                >
                  {item}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </AbsoluteFill>
  );
};

export default ImagemListaTopicos;
